def isAcronym(words: list[str], s: str) -> bool:
    # First, check if the lengths match, as each word contributes exactly one character
    if len(words) != len(s):
        return False

    # Compare each character of s with the first character of the corresponding word
    for i in range(len(words)):
        if words[i][0] != s[i]:
            return False

    return True
