def findLatestTime(s: str) -> str:
    s_list = list(s)

    # Handle the Hour part (HH)
    # The valid range is 00 to 11
    if s_list[0] == '?' and s_list[1] == '?':
        s_list[0] = '1'
        s_list[1] = '1'
    elif s_list[0] == '?':
        # If the second digit is 0 or 1, the first can be 1 (e.g., 10, 11)
        # Otherwise, the first must be 0 (e.g., 02, 09)
        if int(s_list[1]) <= 1:
            s_list[0] = '1'
        else:
            s_list[0] = '0'
    elif s_list[1] == '?':
        # If the first digit is 1, the second can be at most 1 (11)
        # If the first digit is 0, the second can be 9 (09)
        if s_list[0] == '1':
            s_list[1] = '1'
        else:
            s_list[1] = '9'

    # Handle the Minute part (MM)
    # The valid range is 00 to 59
    if s_list[3] == '?':
        s_list[3] = '5'
    if s_list[4] == '?':
        s_list[4] = '9'

    return "".join(s_list)
