import sys

def solve():
    # Read H and W from the first line
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    H = int(input_data[0])
    W = int(input_data[1])
    grid = input_data[2:]

    # Pre-calculate which cells are "frozen" (adjacent to a magnet)
    # 0: Magnet, 1: Frozen (cannot move from here), 2: Free (can move from here)
    status = [[2 for _ in range(W)] for _ in range(H)]

    for r in range(H):
        for c in range(W):
            if grid[r][c] == '#':
                status[r][c] = 0
                # Mark neighbors as frozen
                for dr, dc in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < H and 0 <= nc < W and grid[nr][nc] == '.':
                        status[nr][nc] = 1

    visited = [[False for _ in range(W)] for _ in range(H)]
    # To track frozen cells visited in the current BFS/DFS to avoid double counting
    # using an integer ID for the current component to avoid re-allocating a set
    frozen_visited_by = [[-1 for _ in range(W)] for _ in range(H)]

    max_degree = 0
    component_id = 0

    for r in range(H):
        for c in range(W):
            # Only start BFS from 'Free' cells that haven't been visited yet
            if status[r][c] == 2 and not visited[r][c]:
                component_id += 1
                count = 0
                stack = [(r, c)]
                visited[r][c] = True

                while stack:
                    curr_r, curr_c = stack.pop()
                    count += 1

                    # If current cell is frozen, we can't move further
                    if status[curr_r][curr_c] == 1:
                        continue

                    # Explore neighbors
                    for dr, dc in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                        nr, nc = curr_r + dr, curr_c + dc
                        if 0 <= nr < H and 0 <= nc < W:
                            st = status[nr][nc]
                            if st == 2 and not visited[nr][nc]:
                                visited[nr][nc] = True
                                stack.append((nr, nc))
                            elif st == 1 and frozen_visited_by[nr][nc] != component_id:
                                # Frozen cells are counted but not used to continue path
                                # and we don't mark them 'visited' globally, only for this component
                                frozen_visited_by[nr][nc] = component_id
                                stack.append((nr, nc))

                if count > max_degree:
                    max_degree = count

    # If there are no Free cells, check if any '.' exists (they will all have degree 1)
    if max_degree == 0:
        for r in range(H):
            for c in range(W):
                if grid[r][c] == '.':
                    print(1)
                    return
        print(0)
    else:
        print(max_degree)

if __name__ == "__main__":
