import sys

def solve():
    # Read all input at once
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    N = int(input_data[0])
    M = int(input_data[1])

    # Initialize distance matrix with infinity
    INF = float('inf')
    dist = [[INF] * N for _ in range(N)]
    for i in range(N):
        dist[i][i] = 0

    idx = 2
    for _ in range(M):
        u = int(input_data[idx]) - 1
        v = int(input_data[idx+1]) - 1
        w = int(input_data[idx+2])
        dist[u][v] = w
        idx += 3

    # Floyd-Warshall to find all-pairs shortest paths
    for k in range(N):
        for i in range(N):
            if dist[i][k] == INF: continue
            for j in range(N):
                if dist[k][j] == INF: continue
                if dist[i][j] > dist[i][k] + dist[k][j]:
                    dist[i][j] = dist[i][k] + dist[k][j]

    # Traveling Salesperson Problem using Dynamic Programming
    # dp[mask][i] = minimum weight to visit set of vertices 'mask' ending at vertex 'i'
    dp = [[INF] * N for _ in range(1 << N)]

    # Initialize starting points
    for i in range(N):
        dp[1 << i][i] = 0

    # Iterate through all subsets of vertices
    for mask in range(1, 1 << N):
        for u in range(N):
            if dp[mask][u] == INF:
                continue

            # Try to visit vertex v next
            for v in range(N):
                if not (mask & (1 << v)):
                    if dist[u][v] != INF:
                        new_mask = mask | (1 << v)
                        new_dist = dp[mask][u] + dist[u][v]
                        if dp[new_mask][v] > new_dist:
                            dp[new_mask][v] = new_dist

    # Find the minimum total weight among all paths that visit all N vertices
    ans = INF
    final_mask = (1 << N) - 1
    for i in range(N):
        ans = min(ans, dp[final_mask][i])

    if ans == INF:
        print("No")
    else:
        print(ans)

if __name__ == "__main__":
    solve()
