def numberOfBeautifulIntegers(low: int, high: int, k: int) -> int:
    from functools import lru_cache

    def count_beautiful(n: int) -> int:
        s = str(n)

        @lru_cache(None)
        def dp(idx: int, diff: int, remainder: int, is_less: bool, is_started: bool) -> int:
            if idx == len(s):
                # diff is (even_count - odd_count). Beautiful means diff == 0 and remainder == 0.
                return 1 if is_started and diff == 0 and remainder == 0 else 0

            res = 0
            # Option to not start the number yet (leading zeros)
            if not is_started:
                res += dp(idx + 1, 0, 0, True, False)

            upper = int(s[idx]) if not is_less else 9
            lower = 1 if not is_started else 0

            for digit in range(lower, upper + 1):
                new_diff = diff + (1 if digit % 2 == 0 else -1)
                new_remainder = (remainder * 10 + digit) % k
                new_is_less = is_less or (digit < upper)
                res += dp(idx + 1, new_diff, new_remainder, new_is_less, True)

            return res

        return dp(0, 0, 0, False, False)

    return count_beautiful(high) - count_beautiful(low - 1)
