def minBalancedPartitions(s: str) -> int:
    n = len(s)

    def is_balanced(sub):
        if not sub:
            return False
        counts = {}
        for char in sub:
            counts[char] = counts.get(char, 0) + 1

        freq_set = set(counts.values())
        return len(freq_set) == 1

    # dp[i] will store the minimum number of substrings for s[i:]
    dp = [float('inf')] * (n + 1)
    dp[n] = 0

    # Pre-calculate balanced status for all substrings to optimize
    # balanced[i][j] is true if s[i:j] is balanced
    balanced = [[False] * (n + 1) for _ in range(n)]
    for i in range(n):
        counts = {}
        distinct_chars = 0
        max_freq = 0
        for j in range(i, n):
            char = s[j]
            if char not in counts:
                counts[char] = 0
                distinct_chars += 1
            counts[char] += 1

            # Substring length must be a multiple of distinct characters
            length = j - i + 1
            if length % distinct_chars == 0:
                target = length // distinct_chars
                # Check if all chars in current counts have the target frequency
                is_bal = True
                for val in counts.values():
                    if val != target:
                        is_bal = False
                        break
                balanced[i][j+1] = is_bal

    for i in range(n - 1, -1, -1):
        for j in range(i + 1, n + 1):
            if balanced[i][j]:
                dp[i] = min(dp[i], 1 + dp[j])

    return dp[0]
