import sys
from collections import deque

def solve():
    # Read H and W
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    H = int(input_data[0])
    W = int(input_data[1])

    grid = []
    start_pos = None
    goal_pos = None
    for r in range(H):
        row_str = input_data[2 + r]
        grid.append(row_str)
        for c in range(W):
            if row_str[c] == 'S':
                start_pos = (r, c)
            elif row_str[c] == 'T':
                goal_pos = (r, c)

    N_idx = 2 + H
    N = int(input_data[N_idx])

    # Map coordinates to medicine energy, and store medicine locations
    meds = {}
    for i in range(N):
        r = int(input_data[N_idx + 1 + i*3]) - 1
        c = int(input_data[N_idx + 2 + i*3]) - 1
        e = int(input_data[N_idx + 3 + i*3])
        meds[(r, c)] = e

    # Special case: Must have a medicine at start to move at all
    if start_pos not in meds:
        print("No")
        return

    # We treat medicine locations (+ Start and Goal) as nodes in a graph
    # node_coords maps coordinate to an ID
    nodes = [start_pos]
    for pos in meds.keys():
        if pos != start_pos:
            nodes.append(pos)

    # Check if goal is a medicine spot, if not add it as a node
    goal_node_idx = -1
    for i, pos in enumerate(nodes):
        if pos == goal_pos:
            goal_node_idx = i
            break
    if goal_node_idx == -1:
        goal_node_idx = len(nodes)
        nodes.append(goal_pos)

    num_nodes = len(nodes)
    adj = [[] for _ in range(num_nodes)]

    # For each node that has a medicine, find which other nodes it can reach
    for i in range(num_nodes):
        pos = nodes[i]
        if pos not in meds:
            continue

        energy = meds[pos]
        # BFS to find reachable nodes from 'pos' within 'energy' steps
        distances = {pos: 0}
        q = deque([pos])

        while q:
            curr_r, curr_c = q.popleft()
            d = distances[(curr_r, curr_c)]

            if d >= energy:
                continue

            for dr, dc in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nr, nc = curr_r + dr, curr_c + dc
                if 0 <= nr < H and 0 <= nc < W and grid[nr][nc] != '#' and (nr, nc) not in distances:
                    distances[(nr, nc)] = d + 1
                    q.append((nr, nc))

        # Connect node i to any node j that was reached
        for j in range(num_nodes):
            if i == j: continue
            if nodes[j] in distances:
                adj[i].append(j)

    # Final BFS/DFS on the meta-graph of medicines
    visited = [False] * num_nodes
    q = deque([0]) # Start is always index 0
    visited[0] = True

    while q:
        u = q.popleft()
        if u == goal_node_idx:
            print("Yes")
            return

        for v in adj[u]:
            if not visited[v]:
                visited[v] = True
                q.append(v)

    print("No")

if __name__ == "__main__":
    solve()
