def palindromePartition(s: str, k: int) -> int:
    n = len(s)

    def get_changes(sub):
        m = len(sub)
        if m < 2:
            return float('inf')

        min_cost = float('inf')
        # Find all divisors d such that 1 <= d < m and m % d == 0
        for d in range(1, m):
            if m % d == 0:
                current_cost = 0
                # For each divisor d, the string is a semi-palindrome if 
                # for all 0 <= i < d, the sequence sub[i], sub[i+d], ..., sub[i+(m/d-1)*d]
                # is a palindrome.
                num_groups = m // d
                for i in range(d):
                    # Extract the characters at indices i, i+d, i+2d...
                    # and calculate changes to make this sequence a palindrome
                    left = 0
                    right = num_groups - 1
                    while left < right:
                        if sub[i + left * d] != sub[i + right * d]:
                            current_cost += 1
                        left += 1
                        right -= 1
                min_cost = min(min_cost, current_cost)
        return min_cost

    # Precompute costs for all possible substrings s[i:j]
    cost = [[0] * (n + 1) for _ in range(n)]
    for i in range(n):
        for j in range(i + 2, n + 1):
            cost[i][j] = get_changes(s[i:j])

    # dp[i][j] is the min changes to partition s[:i] into j semi-palindromes
    dp = [[float('inf')] * (k + 1) for _ in range(n + 1)]
    dp[0][0] = 0

    for j in range(1, k + 1): # Number of partitions
        for i in range(1, n + 1): # End index of the string
            for p in range(0, i - 1): # Start index of the last substring (length >= 2)
                if dp[p][j-1] != float('inf'):
                    dp[i][j] = min(dp[i][j], dp[p][j-1] + cost[p][i])

    return int(dp[n][k])
