def shortestSubstrings(arr):
    n = len(arr)
    ans = [""] * n

    # Pre-calculate a frequency map of all substrings in the entire array.
    # We need to know if a substring appears in any other string.
    # A dictionary mapping substring -> set of indices where it appears.
    substring_map = {}
    for i in range(n):
        s = arr[i]
        m = len(s)
        # Use a set to avoid counting multiple occurrences within the same string twice
        unique_subs = set()
        for length in range(1, m + 1):
            for start in range(m - length + 1):
                unique_subs.add(s[start:start+length])

        for sub in unique_subs:
            if sub not in substring_map:
                substring_map[sub] = 0
            substring_map[sub] += 1

    for i in range(n):
        s = arr[i]
        m = len(s)
        best_sub = ""

        # Try all possible substrings of arr[i]
        # Iterate by length first to find the shortest
        for length in range(1, m + 1):
            candidates = []
            for start in range(m - length + 1):
                sub = s[start:start+length]
                # If this substring appears only in this string (count == 1)
                if substring_map[sub] == 1:
                    candidates.append(sub)

            if candidates:
                # If multiple shortest substrings exist, pick the lexicographically smallest
                best_sub = min(candidates)
                break

        ans[i] = best_sub

    return ans
