def stringIndices(wordsContainer, wordsQuery):
    class TrieNode:
        def __init__(self):
            self.children = {}
            # Stores the index of the word in wordsContainer that:
            # 1. Shares the suffix represented by the path to this node.
            # 2. Is the shortest among such words.
            # 3. Appeared first if lengths are tied.
            self.best_idx = -1

    root = TrieNode()

    # Global best for the root (empty suffix case)
    global_best_idx = 0
    min_len = len(wordsContainer[0])
    for i in range(1, len(wordsContainer)):
        if len(wordsContainer[i]) < min_len:
            min_len = len(wordsContainer[i])
            global_best_idx = i

    root.best_idx = global_best_idx

    def update_best(node, word_idx):
        if node.best_idx == -1:
            node.best_idx = word_idx
            return

        current_best_idx = node.best_idx
        if len(wordsContainer[word_idx]) < len(wordsContainer[current_best_idx]):
            node.best_idx = word_idx
        elif len(wordsContainer[word_idx]) == len(wordsContainer[current_best_idx]):
            if word_idx < current_best_idx:
                node.best_idx = word_idx

    # Build the Trie using reversed words (suffixes become prefixes)
    for i, word in enumerate(wordsContainer):
        curr = root
        # Update root's best index logic is handled during initialization
        # but we re-apply for every word to ensure consistency
        update_best(curr, i)

        for char in reversed(word):
            if char not in curr.children:
                curr.children[char] = TrieNode()
            curr = curr.children[char]
            update_best(curr, i)

    ans = []
    for query in wordsQuery:
        curr = root
        last_valid_idx = root.best_idx
        for char in reversed(query):
            if char in curr.children:
                curr = curr.children[char]
                last_valid_idx = curr.best_idx
            else:
                break
        ans.append(last_valid_idx)

    return ans
