    # Top-left 3x3 must be black (#).
    # Bottom-right 3x3 must be black (#).
    # Cells adjacent to these two 3x3 areas must be white (.).

    def is_tak_code(r, c):
        # r, c are 0-indexed top-left corner of the 9x9 region

        # 1. Top-left 3x3 region (black)
        for i in range(3):
            for j in range(3):
                if S[r + i][c + j] != '#':
                    return False

        # 2. Bottom-right 3x3 region (black)
        for i in range(6, 9):
            for j in range(6, 9):
                if S[r + i][c + j] != '#':
                    return False

        # 3. Neighbors of top-left 3x3 (white)
        # Horizontal neighbors: (0,3), (1,3), (2,3)
        # Vertical neighbors: (3,0), (3,1), (3,2)
        # Diagonal neighbor: (3,3)
        for i in range(4):
            # Column c+3 boundary
            if i <= 3:
                if S[r + i][c + 3] != '.':
                    return False
            # Row r+3 boundary
            if i <= 3:
                if S[r + 3][c + i] != '.':
                    return False

        # 4. Neighbors of bottom-right 3x3 (white)
        # Horizontal neighbors: (6,5), (7,5), (8,5)
        # Vertical neighbors: (5,6), (5,7), (5,8)
        # Diagonal neighbor: (5,5)
        for i in range(5, 9):
            # Column c+5 boundary
            if S[r + i][c + 5] != '.':
                return False
        for j in range(5, 9):
            # Row r+5 boundary
            if S[r + 5][c + j] != '.':
                return False

        return True

    # Iterate through every possible 9x9 top-left corner
    # Grid is N x M, so top-left corner (r, c) can range:
    # 0 <= r <= N-9
    # 0 <= c <= M-9
    for r in range(N - 8):
        for c in range(M - 8):
            if is_tak_code(r, c):
                # Problem asks for 1-based indexing
                print(f"{r + 1} {c + 1}")

