def minAnagramLength(s: str) -> int:
    from collections import Counter

    n = len(s)

    def check(length):
        # The number of blocks we will have
        num_blocks = n // length
        # Get the character count of the first block
        first_block_counts = Counter(s[:length])

        # Check every subsequent block of size 'length'
        for i in range(length, n, length):
            current_block_counts = Counter(s[i:i+length])
            if current_block_counts != first_block_counts:
                return False
        return True

    # The possible lengths of t must be divisors of n
    # We check divisors in increasing order to find the minimum length
    for length in range(1, n + 1):
        if n % length == 0:
            if check(length):
                return length
    return n
