import math
from itertools import combinations

def findKthSmallest(coins, k):
    def gcd(a, b):
        while b:
            a, b = b, a % b
        return a

    def lcm(a, b):
        if a == 0 or b == 0:
            return 0
        return abs(a * b) // gcd(a, b)

    # Precompute LCMs for all possible subsets of coins to use Inclusion-Exclusion Principle
    n = len(coins)
    subset_lcms = []
    for r in range(1, n + 1):
        for combo in combinations(coins, r):
            res_lcm = combo[0]
            for i in range(1, len(combo)):
                res_lcm = lcm(res_lcm, combo[i])
            subset_lcms.append((res_lcm, r))

    def count_multiples(m):
        count = 0
        for val, size in subset_lcms:
            if size % 2 == 1:
                count += m // val
            else:
                count -= m // val
        return count

    # Binary search for the k-th smallest amount
    low = 1
    high = min(coins) * k
    ans = high

    while low <= high:
        mid = (low + high) // 2
        if count_multiples(mid) >= k:
            ans = mid
            high = mid - 1
        else:
            low = mid + 1

    return ans
