def incremovableSubarrayCount(nums: list[int]) -> int:
    n = len(nums)
    count = 0

    # Iterate through all possible subarrays [i, j]
    for i in range(n):
        for j in range(i, n):
            # Form the new array by removing the subarray nums[i:j+1]
            remaining = nums[:i] + nums[j+1:]

            # Check if the remaining array is strictly increasing
            is_increasing = True
            for k in range(len(remaining) - 1):
                if remaining[k] >= remaining[k+1]:
                    is_increasing = False
                    break

            if is_increasing:
                count += 1

    return count
