def minimumString(a: str, b: str, c: str) -> str:
    from itertools import permutations

    def merge(s1, s2):
        """Merges s2 into s1 by overlapping them as much as possible."""
        if s2 in s1:
            return s1
        for i in range(min(len(s1), len(s2)), 0, -1):
            if s1.endswith(s2[:i]):
                return s1 + s2[i:]
        return s1 + s2

    def solve(s1, s2, s3):
        """Combines three strings in the order s1, s2, s3."""
        res = merge(merge(s1, s2), s3)
        return res

    candidates = []
    # Try every permutation of the three strings to find the minimum length
    for p in permutations([a, b, c]):
        candidates.append(solve(p[0], p[1], p[2]))

    # Find the minimum length among all constructed strings
    min_len = min(len(s) for s in candidates)

    # Filter candidates that have the minimum length
    best_candidates = [s for s in candidates if len(s) == min_len]

    # Return the lexicographically smallest one among the shortest candidates
    return min(best_candidates)
