import sys
from collections import deque

def solve():
    # Read input from stdin
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    H = int(input_data[0])
    W = int(input_data[1])
    T = int(input_data[2])
    grid = input_data[3:]

    nodes = []
    start_node = None
    goal_node = None
    candy_nodes = []

    for r in range(H):
        for c in range(W):
            char = grid[r][c]
            if char == 'S':
                start_node = (r, c)
            elif char == 'G':
                goal_node = (r, c)
            elif char == 'o':
                candy_nodes.append((r, c))

    # Organize points of interest: S, then candies, then G
    poi = [start_node] + candy_nodes + [goal_node]
    num_poi = len(poi)
    num_candies = len(candy_nodes)

    # Precompute distances between all POIs using BFS
    dist_matrix = [[float('inf')] * num_poi for _ in range(num_poi)]

    for i in range(num_poi):
        sr, sc = poi[i]
        dists = [[-1] * W for _ in range(H)]
        dists[sr][sc] = 0
        queue = deque([(sr, sc)])

        while queue:
            r, c = queue.popleft()
            d = dists[r][c]
            for dr, dc in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nr, nc = r + dr, c + dc
                if 0 <= nr < H and 0 <= nc < W and grid[nr][nc] != '#' and dists[nr][nc] == -1:
                    dists[nr][nc] = d + 1
                    queue.append((nr, nc))

        for j in range(num_poi):
            tr, tc = poi[j]
            if dists[tr][tc] != -1:
                dist_matrix[i][j] = dists[tr][tc]

    # Check if goal is reachable at all
    if dist_matrix[0][num_poi - 1] > T:
        print("-1")
        return

    # TSP-like DP: dp[mask][i] = min distance to visit set 'mask' of candies ending at candy 'i'
    # mask is a bitmask for the candy_nodes (indices 1 to num_candies in poi)
    dp = [[float('inf')] * num_candies for _ in range(1 << num_candies)]

    # Initialize from start node to each candy
    for i in range(num_candies):
        dp[1 << i][i] = dist_matrix[0][i + 1]

    for mask in range(1, 1 << num_candies):
        for i in range(num_candies):
            if dp[mask][i] > T:
                continue
            for j in range(num_candies):
                if not (mask & (1 << j)):
                    new_mask = mask | (1 << j)
                    new_dist = dp[mask][i] + dist_matrix[i + 1][j + 1]
                    if new_dist < dp[new_mask][j]:
                        dp[new_mask][j] = new_dist

    ans = 0
    # Case where 0 candies are visited
    if dist_matrix[0][num_poi-1] <= T:
        ans = 0

    # Check all subsets of candies and see if we can reach Goal from the last candy
    for mask in range(1, 1 << num_candies):
        count = bin(mask).count('1')
        for i in range(num_candies):
            if dp[mask][i] + dist_matrix[i + 1][num_poi - 1] <= T:
                if count > ans:
                    ans = count

    print(ans)

if __name__ == "__main__":
    solve()

