def isGood(nums):
    """
    Checks if the given array nums is a permutation of base[n] = [1, 2, ..., n-1, n, n].
    n is determined by the maximum element in the array.
    """
    if not nums:
        return False

    n = max(nums)

    # base[n] has length n + 1
    if len(nums) != n + 1:
        return False

    # Count occurrences of each number
    counts = {}
    for x in nums:
        counts[x] = counts.get(x, 0) + 1

    # Check if 1 to n-1 appear exactly once
    for i in range(1, n):
        if counts.get(i) != 1:
            return False

    # Check if n appears exactly twice
    if counts.get(n) != 2:
        return False

    return True
