def punishmentNumber(n: int) -> int:
    def can_partition(s, target):
        if not s:
            return target == 0
        if target < 0:
            return False

        # Try partitioning the string starting from index 0
        for i in range(1, len(s) + 1):
            val = int(s[:i])
            if val > target:
                break
            if can_partition(s[i:], target - val):
                return True
        return False

    total_punishment = 0
    for i in range(1, n + 1):
        square_val = i * i
        if can_partition(str(square_val), i):
            total_punishment += square_val

    return total_punishment
