def minimumCost(source: str, target: str, original: list[str], changed: list[str], cost: list[int]) -> int:
    # Initialize a distance matrix for 26 lowercase English letters
    # Use float('inf') to represent infinity
    dist = [[float('inf')] * 26 for _ in range(26)]

    # Distance from a character to itself is always 0
    for i in range(26):
        dist[i][i] = 0

    # Fill the distance matrix with the given conversion costs
    for u_char, v_char, w in zip(original, changed, cost):
        u = ord(u_char) - ord('a')
        v = ord(v_char) - ord('a')
        # If multiple costs exist for the same pair, keep the minimum
        dist[u][v] = min(dist[u][v], w)

    # Floyd-Warshall algorithm to find the shortest path between all pairs of characters
    for k in range(26):
        for i in range(26):
            if dist[i][k] == float('inf'):
                continue
            for j in range(26):
                if dist[k][j] < float('inf'):
                    if dist[i][j] > dist[i][k] + dist[k][j]:
                        dist[i][j] = dist[i][k] + dist[k][j]

    total_cost = 0
    for s_char, t_char in zip(source, target):
        if s_char == t_char:
            continue

        u = ord(s_char) - ord('a')
        v = ord(t_char) - ord('a')

        c = dist[u][v]
        # If a character transformation is impossible, return -1
        if c == float('inf'):
            return -1
        total_cost += c

    return int(total_cost)
