def countCompleteSubstrings(word: str, k: int) -> int:
    def solve_segment(segment):
        count = 0
        n = len(segment)
        # m represents the number of unique characters in a potential complete substring
        # Since lowercase English letters are 26, m can range from 1 to 26
        for m in range(1, 27):
            window_size = m * k
            if window_size > n:
                break

            freq = [0] * 26
            chars_with_k = 0
            unique_chars = 0

            for i in range(n):
                # Add current character to window
                idx_in = ord(segment[i]) - ord('a')
                if freq[idx_in] == 0:
                    unique_chars += 1
                freq[idx_in] += 1
                if freq[idx_in] == k:
                    chars_with_k += 1
                elif freq[idx_in] == k + 1:
                    chars_with_k -= 1

                # Remove character sliding out of window
                if i >= window_size:
                    idx_out = ord(segment[i - window_size]) - ord('a')
                    if freq[idx_out] == k:
                        chars_with_k -= 1
                    freq[idx_out] -= 1
                    if freq[idx_out] == 0:
                        unique_chars -= 1
                    elif freq[idx_out] == k:
                        chars_with_k += 1

                # If window satisfies condition: m unique characters, each appearing k times
                if chars_with_k == m and unique_chars == m:
                    count += 1
        return count

    total_complete = 0
    start = 0
    n = len(word)

    # Split the word into segments where adjacent characters have diff <= 2
    for i in range(1, n + 1):
        if i == n or abs(ord(word[i]) - ord(word[i-1])) > 2:
            segment = word[start:i]
            total_complete += solve_segment(segment)
            start = i

    return total_complete
