def alternatingSubarray(nums: list[int]) -> int:
    max_len = -1
    n = len(nums)

    for i in range(n):
        for j in range(i + 1, n):
            m = j - i + 1
            is_alternating = True

            # Check the first condition: s1 = s0 + 1
            if nums[i + 1] != nums[i] + 1:
                is_alternating = False
            else:
                # Check the pattern for the whole subarray
                # s_k should alternate between s0 and s1
                # indices i, i+1, i+2, ...
                # nums[i + k] should be nums[i] if k is even, nums[i+1] if k is odd
                for k in range(m):
                    if k % 2 == 0:
                        if nums[i + k] != nums[i]:
                            is_alternating = False
                            break
                    else:
                        if nums[i + k] != nums[i + 1]:
                            is_alternating = False
                            break

            if is_alternating:
                max_len = max(max_len, m)

    return max_len
