    candidates = []

    # Iterate through all possible substrings
    for i in range(n):
        for j in range(i + 1, n + 1):
            sub = s[i:j]
            # Check if the number of '1's is exactly k
            if sub.count('1') == k:
                sub_len = len(sub)
                if sub_len < shortest_len:
                    shortest_len = sub_len
                    candidates = [sub]
                elif sub_len == shortest_len:
                    candidates.append(sub)

    if not candidates:
        return ""

    # Sort candidates lexicographically and return the smallest
    candidates.sort()
    return candidates[0]
