import sys

def solve():
    # Read input from stdin
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    idx = 0
    N = int(input_data[idx])
    H = int(input_data[idx+1])
    W = int(input_data[idx+2])
    idx += 3

    tiles = []
    for _ in range(N):
        a = int(input_data[idx])
        b = int(input_data[idx+1])
        tiles.append((a, b))
        idx += 2

    # grid[r][c] = True if cell is covered
    grid = [[False for _ in range(W)] for _ in range(H)]
    used = [False] * N

    def backtrack(r, c):
        # Find next empty cell
        while r < H:
            if not grid[r][c]:
                break
            c += 1
            if c == W:
                c = 0
                r += 1

        # If all cells are checked, we are done
        if r == H:
            return True

        # Try placing every unused tile
        for i in range(N):
            if not used[i]:
                # Each tile can be placed in two orientations
                orientations = set([(tiles[i][0], tiles[i][1]), (tiles[i][1], tiles[i][0])])
                for h, w in orientations:
                    # Check if tile fits
                    if r + h <= H and c + w <= W:
                        can_place = True
                        for dr in range(h):
                            for dc in range(w):
                                if grid[r + dr][c + dc]:
                                    can_place = False
                                    break
                            if not can_place:
                                break

                        if can_place:
                            # Place tile
                            for dr in range(h):
                                for dc in range(w):
                                    grid[r + dr][c + dc] = True
                            used[i] = True

                            if backtrack(r, c):
                                return True

                            # Backtrack
                            used[i] = False
                            for dr in range(h):
                                for dc in range(w):
                                    grid[r + dr][c + dc] = False
        return False

    if backtrack(0, 0):
        print("Yes")
    else:
        print("No")

