def numberOfPowerfulInt(start: int, finish: int, limit: int, s: str) -> int:
    def count_powerful(num_str: str, limit: int, s: str) -> int:
        n = len(num_str)
        m = len(s)
        if n < m:
            return 0

        from functools import lru_cache

        @lru_cache(None)
        def dp(idx: int, is_less: bool, is_started: bool) -> int:
            # If we reached the suffix part
            if idx == n - m:
                # The remaining part must be exactly the suffix 's'
                # We check if the suffix itself is valid according to num_str
                suffix_val = s
                if not is_less:
                    # Compare suffix with the corresponding part of num_str
                    target_suffix = num_str[n - m:]
                    if suffix_val > target_suffix:
                        return 0
                return 1

            res = 0
            upper = int(num_str[idx]) if not is_less else 9

            # The digit we pick must be <= limit
            for digit in range(upper + 1):
                if digit > limit:
                    break

                new_is_less = is_less or (digit < upper)
                new_is_started = is_started or (digit > 0)

                # We handle the "positive integer" logic implicitly since start >= 1.
                # Leading zeros are allowed during the process as long as the total length matches.
                res += dp(idx + 1, new_is_less, new_is_started)

            return res

        return dp(0, False, False)

    return count_powerful(str(finish), limit, s) - count_powerful(str(start - 1), limit, s)
