def countMatchingSubarrays(nums, pattern):
    """
    Counts the number of subarrays in nums that match the given pattern.
    A subarray matches if for every k in the pattern:
    - nums[i+k+1] > nums[i+k] if pattern[k] == 1
    - nums[i+k+1] == nums[i+k] if pattern[k] == 0
    - nums[i+k+1] < nums[i+k] if pattern[k] == -1
    """
    n = len(nums)
    m = len(pattern)
    count = 0

    # Iterate through all possible starting positions of a subarray of size m + 1
    for i in range(n - m):
        match = True
        # Check if the subarray starting at i matches the pattern
        for k in range(m):
            if pattern[k] == 1:
                if not (nums[i + k + 1] > nums[i + k]):
                    match = False
                    break
            elif pattern[k] == 0:
                if not (nums[i + k + 1] == nums[i + k]):
                    match = False
                    break
            elif pattern[k] == -1:
                if not (nums[i + k + 1] < nums[i + k]):
                    match = False
                    break

        if match:
            count += 1

    return count
