def canTraverseAllPairs(nums: list[int]) -> bool:
    n = len(nums)
    if n == 1:
        return True

    # If there is a 1 in the list and there's more than one element, 
    # it can't be connected to anything.
    if 1 in nums:
        return False

    # Unique elements to speed up prime factorization mapping
    unique_nums = list(set(nums))
    if len(unique_nums) == 1:
        return True

    parent = list(range(n))

    def find(i):
        if parent[i] == i:
            return i
        parent[i] = find(parent[i])
        return parent[i]

    def union(i, j):
        root_i = find(i)
        root_j = find(j)
        if root_i != root_j:
            parent[root_i] = root_j
            return True
        return False

    # prime_to_first_index maps a prime number to the first index in `nums` 
    # that has this prime as a factor.
    prime_to_first_index = {}

    # Precompute primes using a simple sieve for factorization
    max_num = max(unique_nums)
    min_prime = list(range(max_num + 1))
    for i in range(2, int(max_num**0.5) + 1):
        if min_prime[i] == i:
            for j in range(i*i, max_num + 1, i):
                if min_prime[j] == j:
                    min_prime[j] = i

    # Process each unique number and its index in the original array
    # We map back unique values to one of their indices in the original list
    val_to_idx = {val: i for i, val in enumerate(nums)}

    for val in unique_nums:
        idx = val_to_idx[val]
        temp = val
        while temp > 1:
            p = min_prime[temp]
            if p in prime_to_first_index:
                union(idx, prime_to_first_index[p])
            else:
                prime_to_first_index[p] = idx
            while temp % p == 0:
                temp //= p

    # Check if all indices have the same root
    root = find(0)
    for i in range(1, n):
        if find(i) != root:
            return False
    return True
