        if n < 2:
            return False
        for i in range(2, int(n**0.5) + 1):
            if n % i == 0:
                return False
        return True

    # Precompute primes up to 100 as per constraints
    primes = {i for i in range(1, 101) if is_prime(i)}

    first_prime_idx = -1
    last_prime_idx = -1

    for i, num in enumerate(nums):
        if num in primes:
            if first_prime_idx == -1:
                first_prime_idx = i
            last_prime_idx = i

