import sys

def solve():
    # Read the input string and remove any trailing whitespace
    s = sys.stdin.readline().strip()
    if not s:
        return

    n = len(s)

    # If the length is odd, it's impossible to form a valid parenthesis string
    if n % 2 != 0:
        print(0)
        return

    MOD = 998244353

    # dp[j] represents the number of ways to have a balance of 'j' open parentheses
    # A valid parenthesis string must never have a negative balance and must end at 0.
    dp = [0] * (n + 1)
    dp[0] = 1

    for char in s:
        new_dp = [0] * (n + 1)
        if char == '(':
            # Must increment balance
            for j in range(n):
                if dp[j]:
                    new_dp[j + 1] = dp[j]
        elif char == ')':
            # Must decrement balance, balance cannot be negative
            for j in range(1, n + 1):
                if dp[j]:
                    new_dp[j - 1] = dp[j]
        else: # char == '?'
            # Can be either '(' or ')'
            for j in range(n + 1):
                if dp[j]:
                    # Treat as '('
                    if j + 1 <= n:
                        new_dp[j + 1] = (new_dp[j + 1] + dp[j]) % MOD
                    # Treat as ')'
                    if j - 1 >= 0:
                        new_dp[j - 1] = (new_dp[j - 1] + dp[j]) % MOD
        dp = new_dp

    # The answer is the number of ways to end with a balance of 0
    print(dp[0])

