def minimumSum(nums):
    """
    Finds the minimum possible sum of a mountain triplet (i, j, k) 
    where i < j < k, nums[i] < nums[j], and nums[k] < nums[j].
    """
    n = len(nums)
    min_sum = float('inf')
    found = False

    # Given the constraints (n <= 50), a brute force O(n^3) approach is efficient enough.
    for i in range(n):
        for j in range(i + 1, n):
            for k in range(j + 1, n):
                if nums[i] < nums[j] and nums[k] < nums[j]:
                    current_sum = nums[i] + nums[j] + nums[k]
                    if current_sum < min_sum:
                        min_sum = current_sum
                        found = True

