def specialPerm(nums: list[int]) -> int:
    MOD = 10**9 + 7
    n = len(nums)
    # memo[mask][last_idx] stores the number of special permutations 
    # using elements represented by 'mask', ending with nums[last_idx]
    memo = {}

    def solve(mask, last_idx):
        # Base case: all elements are used
        if mask == (1 << n) - 1:
            return 1

        state = (mask, last_idx)
        if state in memo:
            return memo[state]

        count = 0
        for next_idx in range(n):
            # Check if the element is already used
            if not (mask & (1 << next_idx)):
                # Special permutation condition
                if nums[last_idx] % nums[next_idx] == 0 or nums[next_idx] % nums[last_idx] == 0:
                    count = (count + solve(mask | (1 << next_idx), next_idx)) % MOD

        memo[state] = count
        return count

    total_permutations = 0
    # Start the permutation with each element in the array
    for i in range(n):
        total_permutations = (total_permutations + solve(1 << i, i)) % MOD

    return total_permutations
