def maxPartitionsAfterOperations(s: str, k: int) -> int:
    from functools import lru_cache

    # If k is 26, any string can be partitioned in at most 1 step
    # because every character in the alphabet can fit in one partition.
    if k == 26:
        return 1

    n = len(s)

    @lru_cache(None)
    def dp(index, mask, can_change):
        if index == n:
            return 1

        char_idx = ord(s[index]) - ord('a')

        # Case 1: Don't change the current character
        new_mask = mask | (1 << char_idx)
        if bin(new_mask).count('1') > k:
            res = 1 + dp(index + 1, 1 << char_idx, can_change)
        else:
            res = dp(index + 1, new_mask, can_change)

        # Case 2: Try changing the current character (if allowed)
        if can_change:
            # We only care about characters that would actually influence the partition count.
            # 1. Any character already in the mask: effectively no change.
            # 2. A new character that makes the mask count > k: starts a new partition.
            # 3. A new character that keeps the mask count <= k.

            # Optimization: Instead of trying all 26 characters, we observe that 
            # all characters NOT in the current mask are symmetric unless they
            # trigger the > k condition.

            # Try setting to a character that forces a new partition immediately
            # This happens if we pick a char not in mask and bit_count(mask) == k
            if bin(mask).count('1') == k:
                res = max(res, 1 + dp(index + 1, 1 << 0, False)) # 1 << 0 is arbitrary new partition start
            else:
                # Try setting to a character that doesn't force a new partition
                # bit_count(mask) < k, so adding one more distinct char is possible
                res = max(res, dp(index + 1, mask | (1 << 26), False)) # index 26 represents "some new char"

        return res

    # The mask approach above needs to be precise. Let's refine for the change option.
    @lru_cache(None)
    def solve(i, current_mask, changed):
        if i == n:
            return 1

        # Option 1: Keep s[i]
        c_val = ord(s[i]) - ord('a')
        res = 0
        nm = current_mask | (1 << c_val)
        if bin(nm).count('1') > k:
            res = 1 + solve(i + 1, 1 << c_val, changed)
        else:
            res = solve(i + 1, nm, changed)

        # Option 2: Change s[i] to something else
        if not changed:
            # If we change s[i], we want to pick a character that either
            # stays within the k limit or breaks it to maximize future partitions.
            # Trying all 26 is safe given the constraints and memoization.
            for char_idx in range(26):
                nm = current_mask | (1 << char_idx)
                if bin(nm).count('1') > k:
                    res = max(res, 1 + solve(i + 1, 1 << char_idx, True))
                else:
                    res = max(res, solve(i + 1, nm, True))

        return res

    return solve(0, 0, False)
