    # The starting position must be land ('.')
    possible_starts = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] == '.':
                possible_starts.append((r, c))

    # A cell (r, c) is a candidate for the current (final) position if
    # there exists a starting cell (r0, c0) such that the entire path
    # consists only of land cells, and the path ends at (r, c).

    # We will track the current position for each valid starting point.
    # If at any point a path hits a sea cell ('#'), that starting point is invalid.

    valid_final_positions = set()

    for r0, c0 in possible_starts:
        curr_r, curr_c = r0, c0
        possible = True

        # Simulate the path T
        for move in t:
            if move == 'L':
                curr_c -= 1
            elif move == 'R':
                curr_c += 1
            elif move == 'U':
                curr_r -= 1
            elif move == 'D':
                curr_r += 1

            # Check if the new position is within bounds and is land
            # (Perimeter is sea, so bounds check is implicitly handled by '#')
            if grid[curr_r][curr_c] == '#':
                possible = False
                break

        if possible:
            valid_final_positions.add((curr_r, curr_c))

    # The question asks for the number of cells that could be his CURRENT position.
