from itertools import permutations

def solve():
    # Read input from stdin
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    n = int(input_data[0])
    r_str = input_data[1]
    c_str = input_data[2]

    # Possible row configurations: A, B, C and (n-3) dots
    chars = ['A', 'B', 'C'] + ['.'] * (n - 3)

    # Generate all unique permutations for a row
    row_perms = sorted(list(set(permutations(chars))))

    # Pre-filter rows based on the leftmost character constraint R[i]
    rows_by_r = [[] for _ in range(n)]
    for p in row_perms:
        leftmost = None
        for char in p:
            if char != '.':
                leftmost = char
                break
        for i in range(n):
            if leftmost == r_str[i]:
                rows_by_r[i].append(p)

    # Backtracking to fill the grid row by row
    grid = [None] * n
    col_counts = [[0]*3 for _ in range(n)] # To track A, B, C counts in each column
    char_to_idx = {'A': 0, 'B': 1, 'C': 2}

    def backtrack(row_idx):
        if row_idx == n:
            # Check column top-most character constraint C
            for j in range(n):
                topmost = None
                for i in range(n):
                    if grid[i][j] != '.':
                        topmost = grid[i][j]
                        break
                if topmost != c_str[j]:
                    return False
            return True

        for p in rows_by_r[row_idx]:
            # Pruning: check if adding this row violates the "exactly one A, B, C per column" rule
            possible = True
            for j in range(n):
                char = p[j]
                if char != '.':
                    idx = char_to_idx[char]
                    if col_counts[j][idx] > 0:
                        possible = False
                        break

            if not possible:
                continue

            # Apply row
            grid[row_idx] = p
            for j in range(n):
                if p[j] != '.':
                    col_counts[j][char_to_idx[p[j]]] += 1

            # Recurse
            if backtrack(row_idx + 1):
                return True

            # Backtrack
            for j in range(n):
                if p[j] != '.':
                    col_counts[j][char_to_idx[p[j]]] -= 1

        return False

    if backtrack(0):
        print("Yes")
        for row in grid:
            print("".join(row))
    else:
        print("No")

