def findMinimumOperations(s1: str, s2: str, s3: str) -> int:
    # To make strings equal by deleting the rightmost characters, 
    # they must share a common prefix.
    # The first characters must be identical for any solution to exist.
    if s1[0] != s2[0] or s1[0] != s3[0] or s2[0] != s3[0]:
        return -1

    # Find the length of the longest common prefix
    min_len = min(len(s1), len(s2), len(s3))
    prefix_length = 0

    for i in range(min_len):
        if s1[i] == s2[i] == s3[i]:
            prefix_length += 1
        else:
            break

    # The minimum operations required is the sum of characters to be deleted
    # from each string to reach the common prefix.
    total_len = len(s1) + len(s2) + len(s3)
    return total_len - (3 * prefix_length)
```

